-- ============================================================
-- 4. ACCOUNT TABLE  (main / hub table)
-- ============================================================
CREATE TABLE account (
    account_id       VARCHAR(10)    PRIMARY KEY,
    customer_id      VARCHAR(10)    NOT NULL
                                    REFERENCES customer(cust_id)
                                    ON DELETE RESTRICT,
    branch_id        VARCHAR(10)    NOT NULL
                                    REFERENCES branch(branch_id),
    account_balance  NUMERIC(15,2)  DEFAULT 0.00
                                    CONSTRAINT chk_balance
                                    -- Loan (LD) accounts carry a negative
                                    -- balance (money owed); every other
                                    -- scheme type must stay non-negative.
                                    CHECK (schm_type = 'LD' OR account_balance >= 0),
    lien_amt         NUMERIC(15,2)  DEFAULT 0.00
                                    CONSTRAINT chk_lien
                                    CHECK (lien_amt >= 0),
    acct_cls_flg     CHAR(1)        DEFAULT 'N'
                                    CONSTRAINT chk_cls_flg
                                    CHECK (acct_cls_flg IN ('Y','N')),
    product_id       VARCHAR(10)    REFERENCES product(product_id),
    schm_type        VARCHAR(5),
    schm_code        VARCHAR(10),
    acct_crncy_code  VARCHAR(5)     DEFAULT 'NPR'
                                    CONSTRAINT chk_ccy
                                    CHECK (acct_crncy_code IN
                                    ('NPR','USD','AUD','EUR','GBP',
                                     'INR','SGD','AED','JPY','CAD')),
    -- Last-changed timestamp: drives stg_account.sql's incremental merge
    -- (only rows with lchg_time newer than the staged table's current max
    -- get re-processed).
    lchg_time        TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
 
