-- ============================================================
-- 6. HIST_TRANSACTIONAL TABLE
-- ============================================================
-- tran_amount is always non-negative (direction is conveyed by
-- tran_particular, not by sign); tran_crncy always matches the
-- referenced account's own acct_crncy_code.
CREATE TABLE hist_transactional (
    tran_id          VARCHAR(15)    PRIMARY KEY,
    account_id       VARCHAR(10)    NOT NULL
                                    REFERENCES account(account_id)
                                    ON DELETE CASCADE,
    branch_id        VARCHAR(10)    NOT NULL
                                    REFERENCES branch(branch_id),
    tran_amount      NUMERIC(15,2)  NOT NULL
                                    CONSTRAINT chk_tran_amount
                                    CHECK (tran_amount >= 0),
    tran_crncy       VARCHAR(5)     DEFAULT 'NPR',
    tran_date        DATE           NOT NULL,
    tran_particular  VARCHAR(100),
    tran_remarks     VARCHAR(200),
    created_date     TIMESTAMP      NOT NULL,
    modified_date    TIMESTAMP      NOT NULL
);

